package com.bus.planner.service;
import com.bus.planner.dto.*; import com.bus.planner.entity.*; import com.bus.planner.enums.*; import com.bus.planner.exception.*; import com.bus.planner.repository.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class BookingService {
 private final BookingRepository bookings; private final UserRepository users; private final BusRepository buses;
 public BookingService(BookingRepository b,UserRepository u,BusRepository bs){bookings=b;users=u;buses=bs;}
 @Transactional public Booking create(BookingRequest r){User u=users.findById(r.userId()).orElseThrow(()->new ResourceNotFoundException("User not found"));Bus bus=buses.findById(r.busId()).orElseThrow(()->new ResourceNotFoundException("Bus not found"));if(bus.getStatus()==BusStatus.Cancelled||bus.getStatus()==BusStatus.Completed)throw new IllegalArgumentException("Booking is not allowed for this bus");if(r.seatNumber()>bus.getTotalSeats())throw new IllegalArgumentException("Invalid seat number");if(bus.getAvailableSeats()<=0)throw new SeatNotAvailableException("No seats are available");if(bookings.existsByBusIdAndSeatNumberAndTravelDateAndStatusNot(bus.getId(),r.seatNumber(),r.travelDate(),BookingStatus.Cancelled))throw new SeatNotAvailableException("Seat is not available");Booking b=new Booking();b.setUser(u);b.setBus(bus);b.setSeatNumber(r.seatNumber());b.setTravelDate(r.travelDate());b.setSource(bus.getRoute().getSource());b.setDestination(bus.getRoute().getDestination());b.setFare(bus.getRoute().getFare());b.setStatus(BookingStatus.Confirmed);bus.setAvailableSeats(bus.getAvailableSeats()-1);buses.save(bus);try{return bookings.saveAndFlush(b);}catch(DataIntegrityViolationException e){throw new SeatNotAvailableException("Seat is not available");}}
 public List<Booking> userBookings(Integer userId){users.findById(userId).orElseThrow(()->new ResourceNotFoundException("User not found"));return bookings.findByUserIdOrderByTravelDateDesc(userId);}
 public Booking get(Integer id){return bookings.findById(id).orElseThrow(()->new ResourceNotFoundException("Booking not found"));}
 @Transactional public Booking cancel(Integer id){Booking b=get(id);if(b.getStatus()!=BookingStatus.Confirmed)throw new IllegalArgumentException("Only a confirmed booking can be cancelled");b.setStatus(BookingStatus.Cancelled);Bus bus=b.getBus();bus.setAvailableSeats(Math.min(bus.getTotalSeats(),bus.getAvailableSeats()+1));buses.save(bus);return bookings.save(b);}
 @Transactional public Booking adminStatus(Integer id,BookingStatus newStatus){Booking b=get(id);BookingStatus old=b.getStatus();if(old==newStatus)return b;Bus bus=b.getBus();if(old==BookingStatus.Confirmed && newStatus==BookingStatus.Cancelled){bus.setAvailableSeats(Math.min(bus.getTotalSeats(),bus.getAvailableSeats()+1));}else if(old==BookingStatus.Cancelled && newStatus==BookingStatus.Confirmed){if(bookings.existsByBusIdAndSeatNumberAndTravelDateAndStatusNot(bus.getId(),b.getSeatNumber(),b.getTravelDate(),BookingStatus.Cancelled))throw new SeatNotAvailableException("Seat is not available");if(bus.getAvailableSeats()<=0)throw new SeatNotAvailableException("No seats are available");bus.setAvailableSeats(bus.getAvailableSeats()-1);}else if(old==BookingStatus.Completed && newStatus==BookingStatus.Confirmed){if(bus.getAvailableSeats()<=0)throw new SeatNotAvailableException("No seats are available");bus.setAvailableSeats(bus.getAvailableSeats()-1);}else if(old==BookingStatus.Confirmed && newStatus==BookingStatus.Completed){} b.setStatus(newStatus);buses.save(bus);return bookings.save(b);}
}
